function writeText(id,value){const el=$(id);if(el.textContent!==String(value))el.textContent=value;}
function writeHTML(id,value){const el=$(id);if(el.innerHTML!==value)el.innerHTML=value;}
function clock(seconds){return Math.floor(seconds/60)+':'+String(Math.floor(seconds%60)).padStart(2,'0');}
function pauseIcon(on){$('pause').textContent=on?'▶':'Ⅱ';$('pause').setAttribute('aria-label',on?'Resume':'Pause');$('pause').title=on?'Resume':'Pause';}
