function updateStatus(){if(race.mode==='paused')writeText('state','PAUSED');else if(race.mode==='countdown')writeText('state','READY');else if(race.mode==='playing')writeText('state',clock(race.time));}
function pause(){if(!$('collection').hidden||!$('championship-panel').hidden)return;if(race.mode==='playing'||race.mode==='countdown'){race.resumeMode=race.mode;race.mode='paused';audio.pause();clearInput();snapshot();pauseIcon(true);updateStatus();}else if(race.mode==='paused'){race.mode=race.resumeMode||'playing';if(tiltOn)recenterTilt();audio.unlock();$('overlay').hidden=true;document.body.classList.remove('in-menu');pauseIcon(false);updateStatus();}}

function openMenu(){$('collection').hidden=true;if(race.mode==='playing'||race.mode==='countdown')pause();modeCopy();$('overlay').hidden=false;}
window.nativePause=()=>{audio.pause();clearInput();if(race.mode==='playing'||race.mode==='countdown')pause();};window.nativeTilt=value=>{if(tiltOn)tiltControl.sample(value,performance.now());};window.nativeTiltReset=()=>{if(tiltOn)recenterTilt();};
