$('results-again').onclick=()=>{if(resultsSetup?.cupId){hideResults();openChampionship();return;}if(resultsSetup){profile.route=resultsSetup.route;raceLevel=RACE_DIFFICULTIES.includes(resultsSetup.difficulty)?resultsSetup.difficulty:raceLevel;save('coast-race-level',raceLevel);commit();}selectedMode=resultsSetup?.mode||'race';save('coast-mode',selectedMode);start();};
document.addEventListener('keydown',e=>{if($('race-results').hidden)return;if(e.key==='Escape'){$('results-menu').click();e.stopImmediatePropagation();}if(e.key==='Tab'){const buttons=[...$('race-results').querySelectorAll('button:not(:disabled)')],i=buttons.indexOf(document.activeElement);e.preventDefault();buttons[(i+(e.shiftKey?-1:1)+buttons.length)%buttons.length]?.focus();}},true);
function display(){$('restart').hidden=!runSetup||race.mode==='ready'||race.mode==='over'||!!runSetup.cupId&&!retryAvailable(profile.championship.active||{results:[],level:'hard'});$('menu-restart').hidden=$('restart').hidden;const career=race.gameMode==='career';writeText('speed',Math.round(race.speed));writeText('distance-label','KM');writeHTML('distance',(race.distance/1000).toFixed(2)+(career?'':' <em>/ '+raceLength(race)/1000+'</em>'));if(!career)$('progress').style.width=Math.min(100,Math.round(race.distance/raceLength(race)*1000)/10)+'%';if(career)writeHTML('stat-label','<img src="assets/coin.svg" class="coin-icon" alt="Run coins">');else writeText('stat-label',race.gameMode==='trial'?'TIME':'POS');writeHTML('stat-value',race.gameMode==='trial'?trialTime(race.time):career?String(race.collected):`${race.mode==='ready'?6:race.place} <em>/ 6</em>`);document.querySelector('.hud').classList.toggle('career',career);writeText('mode-tag',career?`CAREER · ${race.difficulty.toUpperCase()}`:routeName(race.routeId).toUpperCase()+' · '+(race.raceDifficulty||'medium').toUpperCase());if(runSetup?.cupId&&race.mode!=='ready')writeText('mode-tag','CUP '+(runSetup.cupRound+1)+'/'+(runSetup.cupRounds||5)+' · '+routeName(race.routeId).toUpperCase());canvas.dataset.cup=runSetup?.cupId||'';canvas.dataset.cupRound=String(runSetup?.cupRound??'');canvas.dataset.rail=race.rail?'contact':'clear';canvas.dataset.position=race.x.toFixed(2);canvas.dataset.mode=race.mode;canvas.dataset.gameMode=race.gameMode;canvas.dataset.distance=race.distance.toFixed(1);document.querySelector('.game').classList.toggle('rail-contact',race.rail);document.querySelector('.game').classList.toggle('impact',race.impact>0);const raceMode=!career,active=raceMode&&race.nitroTime>0,ready=raceMode&&race.nitro>=99.999&&!active,charge=Math.floor(race.nitro);$('nitro-hud').hidden=!raceMode;if(raceMode){$('nitro-fill').style.strokeDashoffset=String(276.46*(1-race.nitro/100));$('nitro-meter').setAttribute('aria-valuenow',String(charge));writeText('nitro-status',active?'⚡':ready?'READY':charge+'%');$('nitro-hud').classList.toggle('ready',ready);$('nitro-hud').classList.toggle('active',active);}document.querySelector('.gas').classList.toggle('nitro-ready',ready&&race.mode==='playing');document.querySelector('.gas').classList.toggle('nitro-active',active);document.querySelector('.game').classList.toggle('nitro-active',active);document.querySelector('.game').classList.toggle('strip-active',raceMode&&race.boostTime>0);document.querySelector('.game').classList.toggle('nitro-start',active&&race.nitroIgnition>0);canvas.dataset.raceLevel=race.raceDifficulty||raceLevel;canvas.dataset.nitroBubbleHits=String(race.nitroBubbleHits||0);document.body.classList.toggle('race-look',race.gameMode!=='career');canvas.dataset.acceleration=String(race.acceleration||52);canvas.dataset.handling=String(race.handling||1);canvas.dataset.braking=String(race.braking||110);canvas.dataset.nitroDuration=String(race.nitroDuration||3);canvas.dataset.car=race.carId||profile.car;canvas.dataset.world=race.worldId||profile.world;canvas.dataset.route=race.routeId||profile.route;canvas.dataset.routeSection=routeSection(race.routeId,race.distance);canvas.dataset.audio=audio.status;canvas.dataset.soundEvents=String(audio.events);canvas.dataset.nitro=String(charge);canvas.dataset.nitroActive=String(active);canvas.dataset.stripHits=String(race.stripHits);$('countdown').hidden=race.mode!=='countdown'&&!(race.mode==='playing'&&race.goTime>0);writeText('countdown',race.mode==='countdown'?Math.ceil(race.countdown):'GO');canvas.dataset.jump=String((race.jumpY||0).toFixed(2));canvas.dataset.rampHits=String(race.rampHits);canvas.dataset.obstacleHits=String(race.obstacleHits);canvas.dataset.botNitros=String(race.traffic.reduce((n,t)=>n+(t.nitroUses||0),0));canvas.dataset.botBoosts=String(race.traffic.reduce((n,t)=>n+(t.boostHits||0),0));updateStatus();}

function frame(time){canvas.dataset.frameMs=(time-last).toFixed(1);canvas.dataset.elapsed=race.time.toFixed(2);canvas.dataset.steering=race.steering.toFixed(4);canvas.dataset.lateral=race.x.toFixed(3);const rawDt=(time-last)/1000,dt=Math.min(Math.max(rawDt,0),.2)||.016;last=time;if(race.mode==='playing'&&autoQuality.sample(rawDt*1000,driverSettings)){view?.setQuality({...driverSettings,quality:'low'});notice('Auto graphics · Low for smoother play');}if(race.time-journalTime>2){snapshot();journalTime=race.time;}if(race.time<journalTime)journalTime=0;const old=race.mode,coins=race.collected,impacts=race.impactCount,strips=race.stripHits,ramps=race.rampHits,obstacles=race.obstacleHits,bubbles=race.nitroBubbleHits||0,charge=race.nitro;const input={gas:held('ArrowUp'),brake:held('ArrowDown'),steer:((held('ArrowRight')?1:0)-(held('ArrowLeft')?1:0))||(tiltOn?Math.max(-1,Math.min(1,tiltControl.value(time)*driverSettings.sensitivity)):0)};race.cornerAssist=driverSettings.assist;for(let remaining=dt;remaining>1e-7;){const tick=Math.min(remaining,.05);step(race,input,tick);coach.update(race,input,tick);remaining-=tick;}audio.update(race,input);if((race.nitroBubbleHits||0)>bubbles)notice('N₂O +25%');if(race.stripHits>strips)notice('⚡ BOOST');if(race.rampHits>ramps)notice('↗ AIR');if(race.obstacleHits>obstacles)notice('− PACE');if(charge<99.999&&race.nitro>=99.999&&race.nitroTime<=0)notice('N₂O READY');if(race.collected>coins)addWallet(race.collected-coins);if(race.impactCount>impacts)notice(`−${Math.round(race.lastImpactLoss)} KM/H`);if(race.gameMode==='trial'&&trialRecorder&&(race.mode==='playing'||race.mode==='countdown'))trialRecorder.add(race);race.ghostPose=race.gameMode==='trial'?ghostPose(trialReference,race.time):null;if(old==='playing'&&race.mode==='over')finish();if(time-lastHud>80){lastHud=time;updateFeatureHud();display();raceExtras.update(race);driftHud.hidden=!race.drifting;driftHud.textContent='DRIFT · '+(race.driftTime||0).toFixed(1)+' s';}if(race.tutorial){$('mission-hud').hidden=true;writeText('mode-tag','PRACTICE · NO REWARDS');writeText('stat-label','DRIVE');writeText('stat-value','FREE');}$('race-map').hidden=race.tutorial||race.gameMode!=='race'||race.mode==='ready';if(!$('race-map').hidden&&$('overlay').hidden)raceMap.update(race,time);if($('overlay').hidden&&time-lastRender>=(view?.quality.fps===30?32:0)){view?.render(race,Math.min(.2,(time-lastRender)/1000));lastRender=time;}requestAnimationFrame(frame);}
$('mission-hud').onclick=()=>{openMenu();collection('missions');};
$('start').onclick=start;$('pause').onclick=pause;$('resume').onclick=pause;$('menu').onclick=openMenu;const keymap={w:'ArrowUp',s:'ArrowDown',a:'ArrowLeft',d:'ArrowRight'};
addEventListener('keydown',e=>{if(e.target.matches?.('select,input,textarea')||!$('championship-panel').hidden||driverHub.open||coach.open)return;const k=keymap[e.key.toLowerCase()]||e.key;if(k.startsWith('Arrow')){e.preventDefault();if(!$('collection').hidden||!$('overlay').hidden)return;keys.add(k);wakeAudio();if(k==='ArrowUp'&&!e.repeat&&race.mode==='playing'&&gasTap.down(performance.now(),'key:'+e.code))requestNitro();}if(e.key.toLowerCase()==='p'&&!e.repeat)pause();if(e.key.toLowerCase()==='f'&&!e.repeat)$('fullscreen').click();if(e.key.toLowerCase()==='n'&&!e.repeat)requestNitro();if(e.key.toLowerCase()==='m'&&!e.repeat)$('sound').click();});addEventListener('keyup',e=>{const k=keymap[e.key.toLowerCase()]||e.key;keys.delete(k);if(k==='ArrowUp')gasTap.up(performance.now(),'key:'+e.code);});addEventListener('blur',window.nativePause);document.addEventListener('visibilitychange',()=>{if(document.hidden)window.nativePause();});
document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();if(!view||!$('overlay').hidden||!$('collection').hidden||driverHub.open||coach.open)return;if(race.mode==='ready'||race.mode==='over')start();wakeAudio();b.setPointerCapture(e.pointerId);pointers.set(e.pointerId,b.dataset.key);b.classList.add('pressed');if(b.dataset.key==='ArrowUp'&&race.mode==='playing'&&gasTap.down(performance.now(),e.pointerId))requestNitro();};const release=e=>{pointers.delete(e.pointerId);if(b.dataset.key==='ArrowUp')gasTap.up(performance.now(),e.pointerId,e.type!=='pointerup');if(![...pointers.values()].includes(b.dataset.key))b.classList.remove('pressed');};b.onpointerup=release;b.onpointercancel=release;b.onlostpointercapture=release;});
function fullscreenLabel(on){document.documentElement.classList.toggle('immersive',on);$('fullscreen').textContent=on?'↙':'⛶';$('fullscreen').setAttribute('aria-pressed',String(on));$('fullscreen').setAttribute('aria-label',on?'Exit fullscreen':'Fullscreen');$('fullscreen').title=on?'Exit fullscreen':'Fullscreen';}

document.addEventListener('fullscreenchange',()=>{fullscreen=!!document.fullscreenElement;fullscreenLabel(fullscreen);if(!fullscreen)screen.orientation?.unlock?.();setTimeout(()=>view?.resize(),100);});
$('fullscreen').onclick=async()=>{if(window.AndroidMotion){fullscreen=!fullscreen;AndroidMotion.setFullscreen(fullscreen);fullscreenLabel(fullscreen);return;}try{if(document.fullscreenElement){await document.exitFullscreen();return;}if(!document.documentElement.requestFullscreen){notice('Use browser fullscreen; rotate to landscape.');return;}await document.documentElement.requestFullscreen();try{await screen.orientation?.lock?.('landscape');}catch{if(innerWidth<innerHeight)notice('Rotate to landscape.');}}catch{notice('Fullscreen unavailable. Try Chrome.');}};
function recenterTilt(){tiltControl.reset();race.steering=0;}
function tiltLabel(on){steeringChoice=on?'tilt':'buttons';save('coast-steering',steeringChoice);steeringCopy();document.documentElement.classList.toggle('tilt-controls',on);$('tilt').setAttribute('aria-pressed',String(on));$('tilt').setAttribute('aria-label',on?'Disable tilt':'Enable tilt');$('tilt').title=on?'Disable tilt':'Enable tilt';$('tilt-center').hidden=!on;}
function stopTilt(){tiltOn=false;recenterTilt();if(orientationHandler)window.removeEventListener('deviceorientation',orientationHandler);orientationHandler=null;sensorAngle=null;tiltLabel(false);}
$('tilt').onclick=async()=>{if(window.AndroidMotion){tiltOn=!tiltOn;recenterTilt();AndroidMotion.setEnabled(tiltOn);tiltLabel(tiltOn);if(tiltOn)notice('Hold steady to center tilt.');return;}if(tiltOn){stopTilt();return;}try{if(!window.DeviceOrientationEvent)throw Error('Tilt unavailable. Use arrows.');if(typeof DeviceOrientationEvent.requestPermission==='function'&&await DeviceOrientationEvent.requestPermission()!=='granted')throw Error('Tilt denied. Use arrows.');recenterTilt();sensorAngle=null;let received=false;orientationHandler=e=>{const angle=screen.orientation?.angle??window.orientation??0,value=orientationTilt(e.beta,e.gamma,angle);if(value===null)return;received=true;if(sensorAngle!==angle){sensorAngle=angle;recenterTilt();}tiltControl.sample(value,performance.now(),360/22);};window.addEventListener('deviceorientation',orientationHandler);tiltOn=true;tiltLabel(true);notice('Hold steady to center tilt.');setTimeout(()=>{if(!received&&tiltOn){stopTilt();notice('No sensor. Use arrows.');}},3000);}catch(e){stopTilt();notice(e.message);}};
$('tilt-center').onclick=()=>{recenterTilt();notice('Hold steady to center tilt.');};
window.nativeTiltUnavailable=()=>{stopTilt();notice('No sensor. Use arrows.');};addEventListener('resize',()=>view?.resize());
function steeringCopy(){for(const id of ['buttons','tilt'])$('steer-'+id).setAttribute('aria-pressed',String(steeringChoice===id));$('steering-hint').textContent=steeringChoice==='tilt'?'Hold steady, then tilt':'Arrow buttons or A / D';}
for(const l of RACE_DIFFICULTIES)$('level-'+l).onclick=()=>{raceLevel=l;save('coast-race-level',l);modeCopy();};
$('steer-buttons').onclick=()=>{if(window.AndroidMotion)AndroidMotion.setEnabled(false);stopTilt();clearInput();};
$('steer-tilt').onclick=()=>{if(!tiltOn)$('tilt').onclick();};steeringCopy();

function cupEntryCopy(){const cup=profile.championship.active;$('championship-entry').textContent=cup?(cupComplete(cup)?'🏆 RESULTS':'🏆 '+(cup.results.length+1)+'/'+cupRounds(cup).length):'🏆 CUP';$('championship-entry').setAttribute('aria-label',cup?(cupComplete(cup)?'View championship podium':'Continue championship · Round '+(cup.results.length+1)+' of '+cupRounds(cup).length):'Open championships');}
function closeChampionship(){ $('championship-panel').hidden=true;document.body.classList.remove('cup-open');$('overlay').inert=false;$('championship-entry').focus(); }
function openChampionship(){hideResults();openMenu();$('overlay').inert=true;$('championship-panel').hidden=false;document.body.classList.add('cup-open');
 renderChampionship($('championship-panel'),profile,{selectedCup:cupChoice,choose:key=>{if(!cupUnlocked(profile,key)||profile.championship.active&&!cupComplete(profile.championship.active))return;cupChoice=key;if(profile.championship.active){profile.championship.active=null;commit();}openChampionship();},carName,routeName,worldName,stats:id=>carStats(profile,id),appearance:id=>appearanceFor(profile,id),close:closeChampionship,
 create:(setup,key)=>{if(!createChampionship(profile,setup,key))return;if(!commit()){profile.championship.active=null;notice('Saving unavailable · Cup not entered');return;}cupEntryCopy();openChampionship();},
 launch:cup=>{if(runSetup?.cupId===cup.id&&runSetup.cupRound===cup.results.length&&race.mode==='paused'){closeChampionship();pause();return;}start({setup:championshipSetup(cup)});},
 retire:()=>{const cup=profile.championship.active;if(runSetup?.cupId===cup?.id){if(profile.active)recordRun(profile,race,'retired');runSetup=null;race.mode='ready';clearInput();}profile.championship.active=null;commit();openChampionship();},
 newCup:()=>{cupChoice=nextCupChoice(profile);profile.championship.active=null;commit();openChampionship();}});$('championship-panel').focus({preventScroll:true});}
$('championship-entry').onclick=openChampionship;
document.addEventListener('keydown',e=>{if($('championship-panel').hidden)return;if(e.key==='Escape'){e.preventDefault();closeChampionship();e.stopImmediatePropagation();}else if(e.key==='Tab'){const buttons=[...$('championship-panel').querySelectorAll('button:not(:disabled),select')].filter(b=>b.getClientRects().length);const i=buttons.indexOf(document.activeElement);e.preventDefault();buttons[(i+(e.shiftKey?-1:1)+buttons.length)%buttons.length]?.focus();e.stopImmediatePropagation();}},true);

$('start').disabled=true;$('start').textContent='…';$('state').textContent='…';modeCopy();
if(window.AndroidMotion){fullscreen=true;fullscreenLabel(true);document.documentElement.classList.add('android');}
try{view=await createScene(canvas,driverSettings);view.setQuality(driverSettings);document.documentElement.classList.toggle('reduced-motion',driverSettings.reducedMotion);$('start').disabled=false;modeCopy();$('state').textContent='READY';coach.welcome();requestAnimationFrame(frame);}catch(e){console.error(e);$('state').textContent='3D ERROR';$('start').textContent='↻';$('start').disabled=false;$('start').onclick=()=>location.reload();notice('3D unavailable. Try Chrome or update WebView.');}

function updateFeatureHud(){
 const hud=$('run-feature-hud');hud.hidden=race.mode==='ready'||race.mode==='over';if(hud.hidden)return;
 if(race.gameMode==='trial'){const reference=ghostTimeAt(trialReference,race.distance),delta=reference===null?null:race.time-reference;hud.dataset.kind='trial';hud.textContent='⏱ '+trialTime(race.time)+' · '+(delta===null?'FIRST RUN':(delta<=0?'−':'+')+Math.abs(delta).toFixed(2)+' s')+' · PB '+trialTime(trialReference?.time);}
 else if(race.gameMode==='career'){hud.hidden=!race.nearCombo;hud.dataset.kind='combo';hud.textContent='NEAR MISS ×'+Math.min(5,1+Math.floor((race.nearCombo-1)/2))+' · '+race.nearCombo+' streak · '+race.comboTime.toFixed(1)+' s';if(race.nearMisses>lastNear){lastNear=race.nearMisses;notice('NEAR MISS +'+race.lastNearReward+' ◉');}}
 else{const next=race.shortcutActive||shortcutsFor(race.trackProfile,raceLength(race)).find(p=>p.entry>=race.distance&&p.entry-race.distance<180);hud.hidden=!next;hud.dataset.kind='shortcut';if(next)hud.textContent=(next.side>0?'↗ ':'↖ ')+next.name.toUpperCase()+' · '+(race.shortcutActive?'ROUGH · RAMPS':Math.round(next.entry-race.distance)+' m');}
 canvas.dataset.nearMisses=String(race.nearMisses||0);canvas.dataset.nearCombo=String(race.nearCombo||0);canvas.dataset.shortcut=String(!!race.shortcutActive);canvas.dataset.shortcutUses=String(race.shortcutUses||0);
}
